module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg  [7:0] a;
    reg  [7:0] b;
    wire [7:0] s;
    wire       overflow;

    // 2. Instantiate TopModule dut ( ... );
    TopModule dut (
        .a(a),
        .b(b),
        .s(s),
        .overflow(overflow)
    );

    // Task to check results
    integer errors = 0;

    // Reference model function for signed 8-bit addition and overflow
    task check_addition(input [7:0] test_a, input [7:0] test_b);
        reg [8:0] sum_full;
        reg [7:0] expected_s;
        reg       expected_overflow;
        begin
            a = test_a;
            b = test_b;
            #10; // Wait for propagation

            // Compute expected values using signed arithmetic
            sum_full = $signed(test_a) + $signed(test_b);
            expected_s = sum_full[7:0];
            expected_overflow = (~test_a[7] & ~test_b[7] & expected_s[7]) | 
                                ( test_a[7] &  test_b[7] & ~expected_s[7]);

            // 4-State Output Equality using !==
            if (s !== expected_s || overflow !== expected_overflow) begin
                $display("ERROR: a=%0d, b=%0d | Got s=%0d, overflow=%b | Expected s=%0d, overflow=%b", 
                         $signed(test_a), $signed(test_b), $signed(s), overflow, $signed(expected_s), expected_overflow);
                errors = errors + 1;
            end
        end
    endtask

    // 3. Stimulus & self-checking:
    initial begin
        // Initialize inputs
        a = 8'h00;
        b = 8'h00;
        #10;

        // Test vectors: covering normal additions and overflow conditions
        // 1. Zero addition
        check_addition(8'h00, 8'h00);

        // 2. Positive + Positive (No overflow)
        check_addition(8'd10, 8'd20);

        // 3. Positive + Positive (Overflow)
        // Max positive (127) + 1 -> Overflow
        check_addition(8'h7F, 8'h01);

        // 4. Negative + Negative (No overflow)
        check_addition(-8'd10, -8'd20);

        // 5. Negative + Negative (Overflow)
        // Min negative (-128) + (-1) -> Overflow
        check_addition(8'h80, 8'hFF);

        // 6. Positive + Negative (Never overflows)
        check_addition(8'd50, -8'd50);
        check_addition(8'h7F, 8'h80); // 127 + (-128) = -1

        // 7. Bounded loop for randomized/systematic coverage
        begin
            integer i;
            for (i = 0; i < 15; i = i + 1) begin
                check_addition(i * 10, i * 5);
                check_addition(-(i * 8), -(i * 4));
                check_addition(i * 9, -(i * 9));
            end
        end

        // Final Result Display
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
```

